// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Minimal thin-V1 money authority shared by the immutable hook capabilities.
abstract contract MoneyRoles {
    struct RoleState {
        address programmableBeneficiary;
        address treasury;
        address operations;
    }

    struct PendingRoleTransfer {
        bytes32 role;
        address currentAccount;
        address proposedAccount;
    }

    struct CycleBoundOperations {
        bytes32 cycleId;
        address operations;
    }

    bytes32 private constant TREASURY_ROLE = keccak256("TREASURY");
    bytes32 private constant OPERATIONS_ROLE = keccak256("OPERATIONS");

    address private immutable _programmable;
    address private _treasury;
    address private _proposedTreasury;
    address private _operations;
    address private _proposedOperations;
    mapping(address beneficiary => bool) private _treasuryBeneficiaries;
    mapping(bytes32 cycleId => address operations) private _cycleOperations;

    error InvalidInitialRole();
    error UnauthorizedCaller();
    error InvalidSuccessor();
    error InvalidRoleBeneficiary();
    error InvalidDestination();
    error InvalidCycle();
    error CycleAlreadyBound();

    event RoleProposed(
        bytes32 indexed role, address indexed currentAccount, address indexed proposedAccount
    );
    event RoleAccepted(
        bytes32 indexed role, address indexed previousAccount, address indexed currentAccount
    );

    constructor(address programmable, address treasury, address operations) {
        if (
            programmable == address(0) || treasury == address(0) || operations == address(0)
                || programmable == address(this) || treasury == address(this)
                || operations == address(this)
        ) {
            revert InvalidInitialRole();
        }
        _programmable = programmable;
        _treasury = treasury;
        _operations = operations;
        _treasuryBeneficiaries[treasury] = true;
    }

    function proposeTreasury(address successor) external {
        if (msg.sender != _treasury) revert UnauthorizedCaller();
        _validateRoleSuccessor(successor, _treasury);
        _proposedTreasury = successor;
        emit RoleProposed(TREASURY_ROLE, _treasury, successor);
    }

    function acceptTreasury() external {
        address successor = _proposedTreasury;
        if (successor == address(0) || msg.sender != successor) revert UnauthorizedCaller();
        address previous = _treasury;
        _treasury = successor;
        _treasuryBeneficiaries[successor] = true;
        delete _proposedTreasury;
        emit RoleAccepted(TREASURY_ROLE, previous, successor);
    }

    function proposeOperations(address successor) external {
        _requireOperationsHandoverAvailable();
        if (msg.sender != _operations) revert UnauthorizedCaller();
        _validateRoleSuccessor(successor, _operations);
        _validateOperationsSuccessor(successor);
        _proposedOperations = successor;
        emit RoleProposed(OPERATIONS_ROLE, _operations, successor);
    }

    function acceptOperations() external {
        _requireOperationsHandoverAvailable();
        address successor = _proposedOperations;
        if (successor == address(0) || msg.sender != successor) revert UnauthorizedCaller();
        address previous = _operations;
        _operations = successor;
        delete _proposedOperations;
        emit RoleAccepted(OPERATIONS_ROLE, previous, successor);
    }

    function readRoles(bytes32 cycleId)
        external
        view
        returns (
            RoleState memory roles,
            PendingRoleTransfer memory treasuryTransfer,
            PendingRoleTransfer memory operationsTransfer,
            CycleBoundOperations memory cycle
        )
    {
        roles = RoleState({
            programmableBeneficiary: _programmable, treasury: _treasury, operations: _operations
        });
        treasuryTransfer = PendingRoleTransfer({
            role: TREASURY_ROLE, currentAccount: _treasury, proposedAccount: _proposedTreasury
        });
        operationsTransfer = PendingRoleTransfer({
            role: OPERATIONS_ROLE, currentAccount: _operations, proposedAccount: _proposedOperations
        });
        cycle = CycleBoundOperations({ cycleId: cycleId, operations: _cycleOperations[cycleId] });
    }

    function _currentTreasury() internal view returns (address) {
        return _treasury;
    }

    function _currentOperations() internal view returns (address) {
        return _operations;
    }

    function _authorizeTreasuryControl() internal view {
        if (msg.sender != _treasury) revert UnauthorizedCaller();
    }

    function _authorizeProcessClaim(address destination) internal view {
        if (msg.sender != _operations) revert UnauthorizedCaller();
        if (destination != msg.sender) revert InvalidDestination();
    }

    function _requireOperationsHandoverAvailable() internal view virtual { }

    function _clearProposedOperations() internal {
        delete _proposedOperations;
    }

    function _replaceOperationsForEmergencyRotation(address successor)
        internal
        returns (address previous)
    {
        _validateRoleSuccessor(successor, _operations);
        _validateOperationsSuccessor(successor);
        previous = _operations;
        _operations = successor;
        _clearProposedOperations();
    }

    function _validateRoleSuccessor(address successor, address currentAccount)
        internal
        view
        virtual
    {
        if (successor == address(0) || successor == currentAccount || successor == address(this)) {
            revert InvalidSuccessor();
        }
    }

    function _validateOperationsSuccessor(address) internal view virtual { }

    function _authorizeProgrammableClaim(address storedBeneficiary, address destination)
        internal
        view
    {
        if (storedBeneficiary != _programmable) revert InvalidRoleBeneficiary();
        if (msg.sender != storedBeneficiary) revert UnauthorizedCaller();
        if (destination == address(0)) revert InvalidDestination();
    }

    function _authorizeTreasuryClaim(address storedBeneficiary, address destination) internal view {
        if (storedBeneficiary == address(0) || !_treasuryBeneficiaries[storedBeneficiary]) {
            revert InvalidRoleBeneficiary();
        }
        if (msg.sender != storedBeneficiary) revert UnauthorizedCaller();
        if (destination == address(0)) revert InvalidDestination();
    }

    function _bindCycleOperationsTrigger(bytes32 cycleId, address trigger)
        internal
        returns (address boundOperations)
    {
        if (msg.sender != _operations) revert UnauthorizedCaller();
        if (trigger != _operations) revert InvalidDestination();
        if (cycleId == bytes32(0)) revert InvalidCycle();
        if (_cycleOperations[cycleId] != address(0)) revert CycleAlreadyBound();
        boundOperations = _operations;
        _cycleOperations[cycleId] = boundOperations;
    }

    function _bindCycleOperations(bytes32 cycleId, address trigger)
        internal
        returns (address boundOperations)
    {
        return _bindCycleOperationsTrigger(cycleId, trigger);
    }

    function _authorizePayoutFunding(bytes32 cycleId, address payer) internal view {
        address boundOperations = _cycleOperations[cycleId];
        if (boundOperations == address(0)) revert InvalidCycle();
        if (msg.sender != boundOperations) revert UnauthorizedCaller();
        if (payer != boundOperations) revert InvalidDestination();
    }

    function _authorizeHolderPayment(address committedRecipient, address destination)
        internal
        pure
    {
        if (committedRecipient == address(0)) revert InvalidRoleBeneficiary();
        if (destination != committedRecipient) revert InvalidDestination();
    }
}

src/accounting/FeeAccounting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Internal USDG liability ledger for one canonical Hookemon custody address.
/// @dev The final external ABI and USDG adapter remain integration-pending. Inheritors must expose
///      only frozen entry points and implement token calls that fail closed on malformed returns.
abstract contract FeeAccounting {
    uint256 internal constant BPS_DENOMINATOR = 10_000;
    uint256 internal constant TOTAL_FEE_BPS = 300;
    uint256 internal constant PROGRAMMABLE_FEE_BPS = 10;
    uint256 internal constant TREASURY_FEE_BPS = 40;
    uint256 internal constant PROCESS_FEE_BPS =
        TOTAL_FEE_BPS - PROGRAMMABLE_FEE_BPS - TREASURY_FEE_BPS;
    /// @dev programmable-fee-policy.md v1.1.0: "A positive gross quote amount below 1,000
    ///      smallest quote-asset units must revert atomically in the standard profile."
    uint256 internal constant MINIMUM_EXECUTED_USDG = 1_000;

    address private immutable fixedProgrammableBeneficiary;
    mapping(address beneficiary => uint256 amount) private programmableLiabilities;
    mapping(address beneficiary => uint256 amount) private treasuryLiabilities;
    mapping(bytes32 payoutId => uint256 amount) private payoutLiabilities;
    uint256 private processLiabilityAmount;
    uint256 private totalPayoutLiabilityAmount;
    uint256 private totalLiabilityAmount;
    bool private moneyPathEntered;
    /// @dev Cumulative fractional-numerator remainders (each always < BPS_DENOMINATOR) for the
    ///      Programmable, treasury, and process streams. They persist for the canonical pool's
    ///      lifetime and claims never reset them, so fragmenting gross quote volume cannot change
    ///      the lifetime allocation for any owner-approved stream.
    uint256 private programmableRemainder;
    uint256 private treasuryRemainder;
    uint256 private processRemainder;

    /// @dev The three remainder values are this swap's post-commit cumulative state, so an
    ///      off-chain observer can reconcile each stream without a second read.
    event SwapLiabilitiesAccrued(
        uint256 executedUsdg,
        uint256 totalFee,
        address indexed programmableBeneficiary,
        uint256 programmableFee,
        address indexed treasuryBeneficiary,
        uint256 treasuryFee,
        uint256 processFee,
        uint256 programmableRemainderAfter,
        uint256 treasuryRemainderAfter,
        uint256 processRemainderAfter
    );

    /// @dev Emitted whenever the Programmable/treasury beneficiary drains its accrued liability
    ///      (`_claimLiability`, `programmable-fee-policy.md`) so the dashboard's status page can
    ///      index claims without polling `readFeeLiabilities`.
    event ProgrammableClaimed(address indexed destination, uint256 amount);
    event TreasuryClaimed(address indexed destination, uint256 amount);

    error InvalidBeneficiary();
    error InvalidCollectionDelta();
    error InvalidLiabilityAmount();
    error MoneyPathReentrancy();
    error TokenTransferFailed();
    error TokenBalanceDeltaMismatch();
    error InsolventAccounting();
    error SwapBelowMinimumQuote();

    modifier moneyPath() {
        if (moneyPathEntered) revert MoneyPathReentrancy();
        moneyPathEntered = true;
        _;
        moneyPathEntered = false;
    }

    constructor(address programmableBeneficiary) {
        if (programmableBeneficiary == address(0) || programmableBeneficiary == address(this)) {
            revert InvalidBeneficiary();
        }
        fixedProgrammableBeneficiary = programmableBeneficiary;
    }

    /// @dev Called only after P1-002 authenticates finalized executed USDG and collects its fee.
    function _accrueAuthenticatedSwap(uint256 executedUsdg, uint256 balanceBeforeCollection)
        internal
        virtual
    {
        _requireEnteredMoneyPath();
        address treasuryBeneficiary = _currentTreasuryBeneficiary();
        if (treasuryBeneficiary == address(0) || treasuryBeneficiary == address(this)) {
            revert InvalidBeneficiary();
        }

        uint256 balanceAfterCollection = _usdgBalanceOf(address(this));
        (uint256 totalFee, uint256 programmableFee, uint256 treasuryFee, uint256 processFee) =
            _splitLiability(executedUsdg);
        if (
            balanceBeforeCollection < totalLiabilityAmount
                || balanceAfterCollection < balanceBeforeCollection
                || balanceAfterCollection - balanceBeforeCollection != totalFee
        ) {
            revert InvalidCollectionDelta();
        }

        programmableLiabilities[fixedProgrammableBeneficiary] += programmableFee;
        treasuryLiabilities[treasuryBeneficiary] += treasuryFee;
        processLiabilityAmount += processFee;
        totalLiabilityAmount += totalFee;
        _requireSolventAt(balanceAfterCollection);
        emit SwapLiabilitiesAccrued(
            executedUsdg,
            totalFee,
            fixedProgrammableBeneficiary,
            programmableFee,
            treasuryBeneficiary,
            treasuryFee,
            processFee,
            programmableRemainder,
            treasuryRemainder,
            processRemainder
        );
    }

    function _claimProgrammableLiability() internal returns (uint256 amount) {
        return _claimProgrammableLiability(msg.sender);
    }

    function _claimTreasuryLiability() internal returns (uint256 amount) {
        return _claimTreasuryLiability(msg.sender);
    }

    function _claimProgrammableLiability(address destination) internal returns (uint256 amount) {
        amount = _claimLiability(
            programmableLiabilities, msg.sender, destination, programmableLiabilities[msg.sender]
        );
        emit ProgrammableClaimed(destination, amount);
    }

    function _claimTreasuryLiability(address destination) internal returns (uint256 amount) {
        amount = _claimLiability(
            treasuryLiabilities, msg.sender, destination, treasuryLiabilities[msg.sender]
        );
        emit TreasuryClaimed(destination, amount);
    }

    function _claimProgrammableLiability(uint256 requestedAmount, address destination)
        internal
        returns (uint256 amount)
    {
        amount = _claimLiability(programmableLiabilities, msg.sender, destination, requestedAmount);
        emit ProgrammableClaimed(destination, amount);
    }

    function _claimTreasuryLiability(uint256 requestedAmount, address destination)
        internal
        returns (uint256 amount)
    {
        amount = _claimLiability(treasuryLiabilities, msg.sender, destination, requestedAmount);
        emit TreasuryClaimed(destination, amount);
    }

    function _claimLiability(
        mapping(address beneficiary => uint256 amount) storage liabilities,
        address beneficiary,
        address destination,
        uint256 requestedAmount
    ) private moneyPath returns (uint256 amount) {
        if (
            beneficiary == address(0) || beneficiary == address(this) || destination == address(0)
                || destination == address(this)
        ) {
            revert InvalidBeneficiary();
        }

        amount = requestedAmount;
        if (amount == 0 || amount > liabilities[beneficiary]) revert InvalidLiabilityAmount();

        _requireSolvent();

        liabilities[beneficiary] -= amount;
        totalLiabilityAmount -= amount;
        _transferExactUsdg(destination, amount);
        _requireSolvent();
    }

    /// @dev Bounded ledger primitives. The final role-gated money path must hold this component's
    ///      lock around the complete token transfer or same-custody reclassification.
    function _debitProcessLiability(uint256 amount) internal {
        _requireEnteredMoneyPath();
        _requireSolvent();
        if (amount == 0 || amount > processLiabilityAmount) revert InvalidLiabilityAmount();
        processLiabilityAmount -= amount;
        totalLiabilityAmount -= amount;
    }

    function _claimProcessLiability(uint256 amount, address destination)
        internal
        moneyPath
        returns (uint256 claimed)
    {
        _debitProcessLiability(amount);
        _transferExactUsdg(destination, amount);
        _requireSolvent();
        return amount;
    }

    function _creditPayoutLiability(bytes32 payoutId, uint256 amount) internal {
        _requireEnteredMoneyPath();
        if (payoutId == bytes32(0) || amount == 0) revert InvalidLiabilityAmount();
        payoutLiabilities[payoutId] += amount;
        totalPayoutLiabilityAmount += amount;
        totalLiabilityAmount += amount;
        _requireSolvent();
    }

    function _debitPayoutLiability(bytes32 payoutId, uint256 amount) internal {
        _requireEnteredMoneyPath();
        _requireSolvent();
        if (payoutId == bytes32(0) || amount == 0 || amount > payoutLiabilities[payoutId]) {
            revert InvalidLiabilityAmount();
        }
        payoutLiabilities[payoutId] -= amount;
        totalPayoutLiabilityAmount -= amount;
        totalLiabilityAmount -= amount;
    }

    function _transferExactUsdg(address recipient, uint256 amount) internal {
        _requireEnteredMoneyPath();
        if (recipient == address(0) || recipient == address(this) || amount == 0) {
            revert InvalidBeneficiary();
        }

        uint256 sourceBalanceBefore = _usdgBalanceOf(address(this));
        uint256 destinationBalanceBefore = _usdgBalanceOf(recipient);
        if (!_transferUsdg(recipient, amount)) revert TokenTransferFailed();

        uint256 sourceBalanceAfter = _usdgBalanceOf(address(this));
        uint256 destinationBalanceAfter = _usdgBalanceOf(recipient);
        if (
            sourceBalanceAfter > sourceBalanceBefore
                || sourceBalanceBefore - sourceBalanceAfter != amount
                || destinationBalanceAfter < destinationBalanceBefore
                || destinationBalanceAfter - destinationBalanceBefore != amount
        ) {
            revert TokenBalanceDeltaMismatch();
        }
    }

    /// @dev Commits one swap's cumulative-remainder increment. Must be called at most once per
    ///      authenticated swap (from `_accrueAuthenticatedSwap`): it persists the new remainder
    ///      state, so calling it twice for the same swap would double-draw the carried dust.
    ///      Callers that need to know the fee before committing (to size a token collection) must
    ///      use `_previewTotalFee` first and pass the same `executedUsdg` here.
    function _splitLiability(uint256 executedUsdg)
        internal
        returns (uint256 totalFee, uint256 programmableFee, uint256 treasuryFee, uint256 processFee)
    {
        _requireMinimumExecutedUsdg(executedUsdg);
        (programmableFee, programmableRemainder) =
            _cumulativeIncrement(executedUsdg, PROGRAMMABLE_FEE_BPS, programmableRemainder);
        (treasuryFee, treasuryRemainder) =
            _cumulativeIncrement(executedUsdg, TREASURY_FEE_BPS, treasuryRemainder);
        (processFee, processRemainder) =
            _cumulativeIncrement(executedUsdg, PROCESS_FEE_BPS, processRemainder);
        totalFee = programmableFee + treasuryFee + processFee;
    }

    /// @dev Side-effect-free preview of what `_splitLiability(executedUsdg)` would return if
    ///      called right now. Safe to call multiple times (e.g. once in `beforeSwap` to size the
    ///      delta, once in `afterSwap` to validate it) as long as nothing commits a mutation to
    ///      the remainder state in between within the same transaction.
    function _previewTotalFee(uint256 executedUsdg)
        internal
        view
        virtual
        returns (uint256 totalFee)
    {
        _requireMinimumExecutedUsdg(executedUsdg);
        (uint256 programmableFee,) =
            _cumulativeIncrement(executedUsdg, PROGRAMMABLE_FEE_BPS, programmableRemainder);
        (uint256 treasuryFee,) =
            _cumulativeIncrement(executedUsdg, TREASURY_FEE_BPS, treasuryRemainder);
        (uint256 processFee,) =
            _cumulativeIncrement(executedUsdg, PROCESS_FEE_BPS, processRemainder);
        totalFee = programmableFee + treasuryFee + processFee;
    }

    function _programmableRemainder() internal view returns (uint256) {
        return programmableRemainder;
    }

    function _treasuryRemainder() internal view returns (uint256) {
        return treasuryRemainder;
    }

    function _processRemainder() internal view returns (uint256) {
        return processRemainder;
    }

    /// @dev floor((remainderBefore + executedUsdg * rateBps) / BPS_DENOMINATOR), decomposed to
    ///      avoid overflowing `executedUsdg * rateBps` for large executedUsdg, together with the
    ///      new remainder = (remainderBefore + executedUsdg * rateBps) % BPS_DENOMINATOR.
    ///      `remainderBefore` must already be < BPS_DENOMINATOR; the result preserves that
    ///      invariant for `remainderAfter`.
    function _cumulativeIncrement(uint256 executedUsdg, uint256 rateBps, uint256 remainderBefore)
        private
        pure
        returns (uint256 increment, uint256 remainderAfter)
    {
        uint256 highPart = executedUsdg / BPS_DENOMINATOR * rateBps;
        uint256 lowPart = executedUsdg % BPS_DENOMINATOR * rateBps + remainderBefore;
        increment = highPart + lowPart / BPS_DENOMINATOR;
        remainderAfter = lowPart % BPS_DENOMINATOR;
    }

    function _requireMinimumExecutedUsdg(uint256 executedUsdg) private pure {
        if (executedUsdg != 0 && executedUsdg < MINIMUM_EXECUTED_USDG) {
            revert SwapBelowMinimumQuote();
        }
    }

    function _programmableLiabilityOf(address beneficiary) internal view returns (uint256) {
        return programmableLiabilities[beneficiary];
    }

    function _fixedProgrammableBeneficiary() internal view returns (address) {
        return fixedProgrammableBeneficiary;
    }

    function _treasuryLiabilityOf(address beneficiary) internal view returns (uint256) {
        return treasuryLiabilities[beneficiary];
    }

    function _payoutLiabilityOf(bytes32 payoutId) internal view returns (uint256) {
        return payoutLiabilities[payoutId];
    }

    function _processLiability() internal view returns (uint256) {
        return processLiabilityAmount;
    }

    function _totalPayoutLiability() internal view returns (uint256) {
        return totalPayoutLiabilityAmount;
    }

    function _totalLiability() internal view returns (uint256) {
        return totalLiabilityAmount;
    }

    function _hookUsdgBalance() internal view returns (uint256) {
        return _usdgBalanceOf(address(this));
    }

    function _isSolvent() internal view returns (bool) {
        return _hookUsdgBalance() >= totalLiabilityAmount;
    }

    function _solvencyMargin() internal view returns (uint256) {
        uint256 balance = _hookUsdgBalance();
        if (balance < totalLiabilityAmount) revert InsolventAccounting();
        return balance - totalLiabilityAmount;
    }

    function _requireEnteredMoneyPath() private view {
        if (!moneyPathEntered) revert MoneyPathReentrancy();
    }

    function _requireSolvent() internal view {
        _requireSolventAt(_usdgBalanceOf(address(this)));
    }

    function _requireSolventAt(uint256 balance) private view {
        if (balance < totalLiabilityAmount) revert InsolventAccounting();
    }

    function _currentTreasuryBeneficiary() internal view virtual returns (address);

    function _usdgBalanceOf(address account) internal view virtual returns (uint256);

    function _transferUsdg(address recipient, uint256 amount) internal virtual returns (bool);
}

src/bindings/RobinhoodBindings.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { PoolKey } from "@uniswap/v4-core/src/types/PoolKey.sol";

interface IERC721OwnerOf {
    function ownerOf(uint256 tokenId) external view returns (address);
}

interface IPositionManagerPositionView is IERC721OwnerOf {
    function getPoolAndPositionInfo(uint256 tokenId)
        external
        view
        returns (PoolKey memory poolKey, uint256 positionInfo);

    function getPositionLiquidity(uint256 tokenId) external view returns (uint128 liquidity);
}

library RobinhoodBindings {
    uint256 internal constant ROBINHOOD_CHAIN_ID = 4663;
    uint32 internal constant REQUIREMENTS_REVISION = 54;
    uint16 internal constant ARCHITECTURE_REVISION = 3;
    uint24 internal constant STATIC_LP_FEE = 0;
    uint16 internal constant TOTAL_HOOK_FEE_BPS = 300;
    uint16 internal constant PROGRAMMABLE_FEE_BPS = 10;
    uint16 internal constant TREASURY_FEE_BPS = 40;
    uint16 internal constant MARKET_ALLOCATION_BPS = 9_000;
    uint160 internal constant ALL_HOOK_PERMISSION_MASK = (1 << 14) - 1;
    uint160 internal constant REQUIRED_HOOK_PERMISSION_MASK = 0x20CC;
    int24 internal constant MIN_TICK_SPACING = 1;
    int24 internal constant MAX_TICK_SPACING = 32_767;
    address internal constant ROBINHOOD_USDG = 0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168;
    address internal constant ROBINHOOD_POOL_MANAGER = 0x8366a39CC670B4001A1121B8F6A443A643e40951;
    address internal constant ROBINHOOD_POSITION_MANAGER =
        0x58daec3116aae6D93017bAAea7749052E8a04fA7;
    address internal constant ROBINHOOD_LIQUIDITY_LAUNCHER =
        0x0000FffFBE8efE702c8703aE3477FF5dE3d319C0;
    address internal constant PROGRAMMABLE_GRAPH_FACTORY =
        0x0B6b3F40f84Df25D3bd69238f937096177DD09Bd;
    /// @dev programmable-fee-policy.md's pinned Programmable fee beneficiary. A `Binding` whose
    ///      `programmableBeneficiary` does not match this exact address can never `validate()`,
    ///      so no `ImmutableLaunchBinding` deployment (the frozen preimage every production
    ///      deployment must reproduce) can ever bind to a different Programmable owner.
    address internal constant PROGRAMMABLE_BENEFICIARY = 0x4957f49620AFf3Adbbe8195a4f633E49cc93376c;
    address internal constant OPERATIONS_WALLET = 0xB54AAF746eb1e80AFDb5eb0992a75b08DB2E4384;
    bytes32 internal constant SOURCE_SET_DIGEST =
        0x35ffa674dfdbee0fceef1e64614b3291cd19c2f862fc9fb6c5a0dda7bc25b031;
    bytes32 internal constant ABI_SET_DIGEST =
        0x19419411f02f975f7dc1c62dd948017119d882787c6f5525813f1a60fd8d864e;
    bytes32 internal constant RUNTIME_SET_DIGEST =
        0xa11752c21fc1d8c536e769a57ca10811ae310c5285bd1c84ed2068ec6545595e;

    error AddressPreimageMismatch(address expected, address actual);
    error DuplicateAddress(address value);
    error EmptyDigest();
    error InvalidAddress();
    error InvalidArchitectureRevision(uint16 actual);
    error InvalidChainId(uint256 actual);
    error InvalidFeeContract();
    error InvalidHookPermissionMask(uint160 actual);
    error InvalidKnownProviderIdentity();
    error InvalidMarketAllocation(uint16 actual);
    error InvalidPoolKey();
    error InvalidProgrammableBeneficiary(address actual);
    error InvalidOperationsWallet(address actual);
    error InvalidRequirementsRevision(uint32 actual);
    error MismatchedEvidenceDigest();

    struct Binding {
        uint256 chainId;
        uint32 requirementsRevision;
        uint16 architectureRevision;
        address usdg;
        address hkmn;
        address poolManager;
        address positionManager;
        address launcher;
        address hook;
        address hookDeployer;
        bytes32 hookSalt;
        bytes32 hookInitCodeHash;
        address custody;
        address programmableBeneficiary;
        address treasury;
        address operations;
        address expectedOperations;
        address currency0;
        address currency1;
        int24 tickSpacing;
        bytes32 poolId;
        uint24 poolLpFee;
        uint16 totalHookFeeBasisPoints;
        uint16 programmableFeeBasisPoints;
        uint16 treasuryFeeBasisPoints;
        uint16 marketAllocationBasisPoints;
        uint160 hookPermissionMask;
        bytes32 sourceSetDigest;
        bytes32 abiSetDigest;
        bytes32 runtimeSetDigest;
    }

    function validate(Binding memory binding) internal pure {
        if (binding.chainId != ROBINHOOD_CHAIN_ID) revert InvalidChainId(binding.chainId);
        if (binding.requirementsRevision != REQUIREMENTS_REVISION) {
            revert InvalidRequirementsRevision(binding.requirementsRevision);
        }
        if (binding.architectureRevision != ARCHITECTURE_REVISION) {
            revert InvalidArchitectureRevision(binding.architectureRevision);
        }

        address[11] memory identities = [
            binding.usdg,
            binding.hkmn,
            binding.poolManager,
            binding.positionManager,
            binding.launcher,
            binding.hook,
            binding.hookDeployer,
            binding.custody,
            binding.programmableBeneficiary,
            binding.treasury,
            binding.operations
        ];
        for (uint256 index = 0; index < identities.length; ++index) {
            if (identities[index] == address(0)) revert InvalidAddress();
            for (uint256 other = index + 1; other < identities.length; ++other) {
                if (identities[index] == identities[other]) {
                    revert DuplicateAddress(identities[index]);
                }
            }
        }
        if (
            binding.usdg != ROBINHOOD_USDG || binding.poolManager != ROBINHOOD_POOL_MANAGER
                || binding.positionManager != ROBINHOOD_POSITION_MANAGER
                || binding.launcher != ROBINHOOD_LIQUIDITY_LAUNCHER
        ) revert InvalidKnownProviderIdentity();
        if (binding.programmableBeneficiary != PROGRAMMABLE_BENEFICIARY) {
            revert InvalidProgrammableBeneficiary(binding.programmableBeneficiary);
        }
        if (
            OPERATIONS_WALLET == address(0) || binding.operations != OPERATIONS_WALLET
                || binding.expectedOperations != OPERATIONS_WALLET
        ) {
            revert InvalidOperationsWallet(binding.operations);
        }

        if (
            binding.poolLpFee != STATIC_LP_FEE
                || binding.totalHookFeeBasisPoints != TOTAL_HOOK_FEE_BPS
                || binding.programmableFeeBasisPoints != PROGRAMMABLE_FEE_BPS
                || binding.treasuryFeeBasisPoints != TREASURY_FEE_BPS
                || binding.programmableFeeBasisPoints + binding.treasuryFeeBasisPoints
                    > binding.totalHookFeeBasisPoints
        ) revert InvalidFeeContract();
        address expectedCurrency0 =
            uint160(binding.usdg) < uint160(binding.hkmn) ? binding.usdg : binding.hkmn;
        address expectedCurrency1 = expectedCurrency0 == binding.usdg ? binding.hkmn : binding.usdg;
        if (
            binding.currency0 != expectedCurrency0 || binding.currency1 != expectedCurrency1
                || binding.tickSpacing < MIN_TICK_SPACING || binding.tickSpacing > MAX_TICK_SPACING
                || binding.poolId
                    != keccak256(
                        abi.encode(
                            binding.currency0,
                            binding.currency1,
                            binding.poolLpFee,
                            binding.tickSpacing,
                            binding.hook
                        )
                    )
        ) revert InvalidPoolKey();
        if (binding.marketAllocationBasisPoints != MARKET_ALLOCATION_BPS) {
            revert InvalidMarketAllocation(binding.marketAllocationBasisPoints);
        }
        if (binding.hookPermissionMask != REQUIRED_HOOK_PERMISSION_MASK) {
            revert InvalidHookPermissionMask(binding.hookPermissionMask);
        }
        if (uint160(binding.hook) & ALL_HOOK_PERMISSION_MASK != binding.hookPermissionMask) {
            revert InvalidHookPermissionMask(uint160(binding.hook) & ALL_HOOK_PERMISSION_MASK);
        }

        address expectedHook = address(
            uint160(
                uint256(
                    keccak256(
                        abi.encodePacked(
                            bytes1(0xff),
                            binding.hookDeployer,
                            binding.hookSalt,
                            binding.hookInitCodeHash
                        )
                    )
                )
            )
        );
        if (expectedHook != binding.hook) {
            revert AddressPreimageMismatch(expectedHook, binding.hook);
        }
        if (
            binding.sourceSetDigest == bytes32(0) || binding.abiSetDigest == bytes32(0)
                || binding.runtimeSetDigest == bytes32(0) || binding.hookInitCodeHash == bytes32(0)
        ) revert EmptyDigest();
        if (
            binding.sourceSetDigest != SOURCE_SET_DIGEST || binding.abiSetDigest != ABI_SET_DIGEST
                || binding.runtimeSetDigest != RUNTIME_SET_DIGEST
        ) revert MismatchedEvidenceDigest();
    }

    function digest(Binding memory binding) internal pure returns (bytes32) {
        validate(binding);
        return keccak256(abi.encode("HOOKEMON_IMMUTABLE_LAUNCH_BINDING_R54_A3", binding));
    }
}

contract ImmutableLaunchBinding {
    bytes32 public immutable bindingDigest;
    address public immutable custody;
    address public immutable hook;
    address public immutable poolManager;
    address public immutable positionManager;
    bytes32 public immutable poolId;
    address public immutable operations;
    address public immutable usdg;

    constructor(RobinhoodBindings.Binding memory binding) {
        bytes32 frozenDigest = RobinhoodBindings.digest(binding);
        bindingDigest = frozenDigest;
        custody = binding.custody;
        hook = binding.hook;
        poolManager = binding.poolManager;
        positionManager = binding.positionManager;
        poolId = binding.poolId;
        operations = binding.operations;
        usdg = binding.usdg;
    }
}

contract PermanentPositionCustody {
    address public immutable deployer;
    address public immutable positionManager;
    address public bindingHook;
    uint256 public positionTokenId;
    bool public positionReceived;

    error AlreadyReceived();
    error BindingHookAlreadyConfigured();
    error CustodyHookMismatch(address actualHook);
    error InvalidBindingHook();
    error InvalidPositionManager();
    error InvalidPositionPoolKey();
    error InvalidPositionToken(uint256 actual);
    error InvalidPositionTicks(int24 actualLower, int24 actualUpper);
    error InvalidPositionLiquidity(uint128 actual);
    error NotMintedPosition();
    error PositionAlreadyBound();
    error PositionOwnershipMismatch(address actualOwner);
    error UnauthorizedBindingHook(address actualCaller);
    error UnauthorizedCustodyDeployer(address actualCaller);

    event BindingHookConfigured(address indexed hook);
    event PositionPermanentlyReceived(address indexed positionManager, uint256 indexed tokenId);

    constructor(address manager, uint256 tokenId) {
        if (manager == address(0)) revert InvalidPositionManager();
        deployer = msg.sender;
        positionManager = manager;
        positionTokenId = tokenId;
    }

    function configureBindingHook(address hook) external {
        if (msg.sender != deployer) revert UnauthorizedCustodyDeployer(msg.sender);
        if (hook == address(0)) revert InvalidBindingHook();
        if (bindingHook != address(0)) revert BindingHookAlreadyConfigured();
        if (positionTokenId != 0 || positionReceived) revert PositionAlreadyBound();

        bindingHook = hook;
        emit BindingHookConfigured(hook);
    }

    function finalizePosition() external {
        if (positionTokenId == 0) revert NotMintedPosition();
        _finalizePosition();
    }

    function bindMintedPosition(
        uint256 tokenId,
        PoolKey calldata expectedPoolKey,
        int24 expectedTickLower,
        int24 expectedTickUpper,
        uint256 expectedLiquidity
    ) external {
        if (msg.sender != bindingHook) {
            revert UnauthorizedBindingHook(msg.sender);
        }
        if (positionReceived) revert AlreadyReceived();
        if (positionTokenId != 0) revert InvalidPositionToken(positionTokenId);

        IPositionManagerPositionView manager = IPositionManagerPositionView(positionManager);
        address actualOwner = manager.ownerOf(tokenId);
        if (actualOwner != address(this)) revert PositionOwnershipMismatch(actualOwner);
        (PoolKey memory actualPoolKey, uint256 positionInfo) =
            manager.getPoolAndPositionInfo(tokenId);
        if (address(actualPoolKey.hooks) != msg.sender) {
            revert CustodyHookMismatch(address(actualPoolKey.hooks));
        }
        if (keccak256(abi.encode(actualPoolKey)) != keccak256(abi.encode(expectedPoolKey))) {
            revert InvalidPositionPoolKey();
        }
        (int24 actualTickLower, int24 actualTickUpper) = _ticks(positionInfo);
        if (actualTickLower != expectedTickLower || actualTickUpper != expectedTickUpper) {
            revert InvalidPositionTicks(actualTickLower, actualTickUpper);
        }
        uint128 actualLiquidity = manager.getPositionLiquidity(tokenId);
        if (uint256(actualLiquidity) != expectedLiquidity) {
            revert InvalidPositionLiquidity(actualLiquidity);
        }

        positionTokenId = tokenId;
        positionReceived = true;
        emit PositionPermanentlyReceived(positionManager, tokenId);
    }

    function _finalizePosition() private {
        if (positionReceived) revert AlreadyReceived();
        address actualOwner = IERC721OwnerOf(positionManager).ownerOf(positionTokenId);
        if (actualOwner != address(this)) revert PositionOwnershipMismatch(actualOwner);
        positionReceived = true;
        emit PositionPermanentlyReceived(positionManager, positionTokenId);
    }

    function _ticks(uint256 positionInfo) private pure returns (int24 tickLower, int24 tickUpper) {
        assembly ("memory-safe") {
            tickLower := signextend(2, shr(8, positionInfo))
            tickUpper := signextend(2, shr(32, positionInfo))
        }
    }
}

